import math


def _number(value):
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise TypeError("values must be numeric")
    value = float(value)
    if not math.isfinite(value):
        raise ValueError("values must be finite")
    return value


def evaluate_expression(tokens, variables):
    if not isinstance(tokens, list):
        raise TypeError("tokens must be a list")
    if not isinstance(variables, dict):
        raise TypeError("variables must be a dictionary")
    prepared = {}
    for name, value in variables.items():
        if not isinstance(name, str):
            raise TypeError("variable names must be strings")
        if not name:
            raise ValueError("variable names cannot be empty")
        prepared[name] = _number(value)

    work = tokens
    work.reverse()
    stack = []
    while work:
        token = work.pop()
        if isinstance(token, bool):
            raise TypeError("boolean tokens are invalid")
        if isinstance(token, (int, float)):
            stack.append(_number(token))
        elif isinstance(token, str) and token in {"+", "-", "*", "/"}:
            if len(stack) < 2:
                raise ValueError("missing operand")
            right = stack.pop()
            left = stack.pop()
            if token == "+":
                stack.append(left + right)
            elif token == "-":
                stack.append(left - right)
            elif token == "*":
                stack.append(left * right)
            else:
                stack.append(left / right)
        elif isinstance(token, str):
            if not token:
                raise ValueError("variable names cannot be empty")
            if token not in prepared:
                raise ValueError("unknown variable")
            stack.append(prepared[token])
        else:
            raise TypeError("invalid token type")
    if len(stack) != 1:
        raise ValueError("malformed expression")
    return float(stack[0])

